(()=>{const cards=[...document.querySelectorAll('.journal-list .editorial-card')],search=document.querySelector('#articleSearch');let category='all';const normalize=s=>s.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/\u200c/g,' ').toLowerCase();function filter(){const q=normalize(search?.value.trim()||'');let count=0;cards.forEach(card=>{const show=(category==='all'||card.dataset.category===category)&&normalize(card.textContent).includes(q);card.hidden=!show;if(show)count++});const result=document.querySelector('#articleCount');if(result)result.textContent=count.toLocaleString('fa-IR')+' مقاله منتشرشده';const empty=document.querySelector('#noArticles');if(empty)empty.hidden=count>0}search?.addEventListener('input',filter);document.querySelectorAll('[data-category-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.categoryFilter;document.querySelectorAll('[data-category-filter]').forEach(b=>b.classList.toggle('selected',b===button));filter()}));document.querySelectorAll('time[datetime]').forEach(t=>{const date=new Date(t.dateTime);if(!Number.isNaN(date.getTime()))t.textContent=new Intl.DateTimeFormat('fa-IR',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Tehran'}).format(date)});if(search)filter()})();
